def next_recovery(task):
    state = task.get("state")
    if state is None:
        raise ValueError("Unknown state")

    if state == "running":
        return "wait"
    elif state == "queued":
        return "retry"
    elif state == "failed":
        if task.get("attempts", 0) < task.get("max_attempts", 1):
            return "retry"
        else:
            return "escalate"
    else:
        raise ValueError("Unknown state")

from recovery import next_recovery

import pytest

@pytest.mark.parametrize("task,expected", [
    ({"state": "running"}, "wait"),
    ({"state": "queued"}, "retry"),
    ({"attempts": 2, "max_attempts": 3, "state": "failed"}, "retry"),
    ({"attempts": 3, "max_attempts": 3, "state": "failed"}, "escalate"),
    ({"state": "unknown"}, ValueError),
    ({"state": "running", "attempts": 1}, "wait")
])
def test_next_recovery(task, expected):
    try:
        assert next_recovery(task) == expected
    except ValueError as e:
        assert expected is ValueError

if __name__ == "__main__":
    pytest.main(["-v", "candidate_tests.py"])
